package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class SimilarityMeasureRelationsTest {
 private List<Rational> values(Question q){Matcher m=Pattern.compile("\\d+(?:\\.\\d+)?(?:/\\d+)?").matcher(q.prompt);assertTrue(m.find());assertEquals("1",m.group());assertTrue(m.find());Rational ratio=Expression.number(m.group());assertTrue(m.find());Rational small=Expression.number(m.group());int power=q.skillId.endsWith("volume")?3:q.skillId.endsWith("area")?2:1;Rational factor=Rational.ONE;for(int i=0;i<power;i++)factor=factor.mul(ratio);return power==1?List.of(ratio,small,small.mul(factor)):List.of(ratio,small,factor,small.mul(factor));}
 @Test public void publicMeasuresDetermineEachStepWithMoreThan100DistinctProblemsPerUnit(){Generator g=new Generator(new Random(2040));for(String id:List.of("sec_similarity_length","sec_similarity_area","sec_similarity_volume")){Set<String> prompts=new HashSet<>(),answers=new HashSet<>();Set<Integer> positions=new HashSet<>();for(int i=0;i<1000;i++){Question q=g.next(id,List.of(),i%2==0);var v=values(q);assertTrue(new Checker().check(q,List.of(),List.of(v.get(v.size()-1).toString())).correct());prompts.add(q.prompt);answers.add(v.get(v.size()-1).toString());positions.add(q.correctChoice);verify(q,v);}assertTrue(id,prompts.size()>100);assertTrue(id,answers.size()>100);assertTrue(positions.containsAll(Set.of(0,1,2,3)));}}
 private void verify(Question q,List<Rational> v){String signature=q.signature();StudyDiagram old=q.diagram;Arrays.fill(q.answers,"999999");q.choiceInputs=new Rational[]{Rational.of(999999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertSame(old,q.diagram);assertFalse(p.canTransfer());assertEquals(v.size(),p.size());for(int i=0;i<v.size();i++){assertTrue(p.step(i).accepts(v.get(i).toString()));assertFalse(p.step(i).accepts(v.get(i).add(Rational.ONE).toString()));assertEquals("",p.step(i).after);}assertEquals("닮음비의 두 번째 수 = ",p.step(0).before);assertFalse(p.step(p.size()-1).before.matches(".*[0-9].*"));}
 @Test public void savedFractionalMeasuresAndDraftsPreserveExactMeaning(){for(String id:List.of("sec_similarity_length","sec_similarity_area","sec_similarity_volume")){String figure=id.endsWith("volume")?"입체":"도형",measure=id.endsWith("volume")?"부피":id.endsWith("area")?"넓이":"대응변",particle=id.endsWith("length")?"이":"가";Question q=new Question(id,"두 닮은 "+figure+"의 닮음비가 1:3/2입니다. 작은 "+figure+"의 "+measure+particle+" 5/7일 때 큰 "+figure+"의 "+measure+(id.endsWith("length")?"은":"는")+"?","","99999");verify(q,values(q));HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("9/4",""));p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));d.entries.set(0,"3/2");d.stage=1;var restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("3/2",restored.entries.get(0));}}
}
